import{_ as e,c as a,o,a0 as i}from"./chunks/framework.DKRgXLPU.js";const s=JSON.parse('{"title":"Goal Setting for Elite Athletes","description":"Learn advanced goal-setting strategies used by elite pétanque players to drive continuous improvement and achieve peak performance.","frontmatter":{"title":"Goal Setting for Elite Athletes","description":"Learn advanced goal-setting strategies used by elite pétanque players to drive continuous improvement and achieve peak performance."},"headers":[],"relativePath":"es/blog/elite-goal-setting.md","filePath":"es/blog/elite-goal-setting.md"}');const l=e({name:"es/blog/elite-goal-setting.md"},[["render",function(e,s,l,t,r,n){return o(),a("div",null,[...s[0]||(s[0]=[i('<h1 id="establecimiento-de-objetivos-para-atletas-de-elite" tabindex="-1">Establecimiento de objetivos para atletas de élite <a class="header-anchor" href="#establecimiento-de-objetivos-para-atletas-de-elite" aria-label="Permalink to &quot;Establecimiento de objetivos para atletas de élite&quot;">​</a></h1><p>Establecer metas parece simple: decide qué quieres y trabaja para lograrlo. Pero establecer metas a nivel de élite es más matizado. Las metas correctas aceleran el desarrollo; las incorrectas generan frustración y estancamiento.</p><h2 id="mas-alla-de-los-objetivos-basicos" tabindex="-1">Más allá de los objetivos básicos <a class="header-anchor" href="#mas-alla-de-los-objetivos-basicos" aria-label="Permalink to &quot;Más allá de los objetivos básicos&quot;">​</a></h2><p>La mayoría de los jugadores se fijan objetivos de resultado: «Ganar el campeonato regional». Estos objetivos presentan problemas:</p><ul><li>No puedes controlar completamente los resultados</li><li>Crean presión sin dirección</li><li>El éxito o el fracaso son binarios</li><li>No guían la práctica diaria</li></ul><p>El establecimiento de objetivos de élite es algo más profundo.</p><h2 id="la-jerarquia-de-objetivos" tabindex="-1">La jerarquía de objetivos <a class="header-anchor" href="#la-jerarquia-de-objetivos" aria-label="Permalink to &quot;La jerarquía de objetivos&quot;">​</a></h2><h3 id="nivel-1-metas-de-ensueno-1-5-anos" tabindex="-1">Nivel 1: Metas de ensueño (1-5 años) <a class="header-anchor" href="#nivel-1-metas-de-ensueno-1-5-anos" aria-label="Permalink to &quot;Nivel 1: Metas de ensueño (1-5 años)&quot;">​</a></h3><p>Tus aspiraciones más grandes:</p><ul><li>&quot;Compite a nivel nacional&quot;</li><li>&quot;Ser reconocido como un tirador de élite&quot;</li><li>&quot;Ganar un campeonato importante&quot;</li></ul><p>Estos proporcionan dirección y motivación, pero no se pueden poner en práctica a diario.</p><h3 id="nivel-2-metas-de-rendimiento-temporada-ano" tabindex="-1">Nivel 2: Metas de rendimiento (temporada/año) <a class="header-anchor" href="#nivel-2-metas-de-rendimiento-temporada-ano" aria-label="Permalink to &quot;Nivel 2: Metas de rendimiento (temporada/año)&quot;">​</a></h3><p>Mejoras mensurables en tu juego:</p><ul><li>Aumenta la precisión de disparo del 60% al 70%</li><li>&quot;Reducir los errores no forzados en un 25%&quot;</li><li>&quot;Desarrollar una plombée fiable&quot;</li></ul><p>Estos están bajo su control y son mensurables.</p><h3 id="nivel-3-metas-del-proceso-diarias-semanales" tabindex="-1">Nivel 3: Metas del proceso (diarias/semanales) <a class="header-anchor" href="#nivel-3-metas-del-proceso-diarias-semanales" aria-label="Permalink to &quot;Nivel 3: Metas del proceso (diarias/semanales)&quot;">​</a></h3><p>Las acciones que impulsan la mejora:</p><ul><li>&quot;Rutina completa previa al lanzamiento en cada lanzamiento&quot;</li><li>Practica la visualización durante 10 minutos diarios.</li><li>&quot;Entrena tu técnica de tiro 3 veces por semana&quot;</li></ul><p>Son totalmente controlables y están orientados a alcanzar objetivos de rendimiento.</p><h2 id="el-marco-smart" tabindex="-1">El marco SMART+ <a class="header-anchor" href="#el-marco-smart" aria-label="Permalink to &quot;El marco SMART+&quot;">​</a></h2><p>Vaya más allá de los objetivos SMART básicos:</p><h3 id="especifico" tabindex="-1">Específico <a class="header-anchor" href="#especifico" aria-label="Permalink to &quot;Específico&quot;">​</a></h3><p>No &quot;mejorar mi puntería&quot;, sino &quot;desarrollar una media punta consistente que aterrice a 30 cm del objetivo desde 8 metros&quot;.</p><h3 id="mensurable" tabindex="-1">Mensurable <a class="header-anchor" href="#mensurable" aria-label="Permalink to &quot;Mensurable&quot;">​</a></h3><p>Define cómo harás el seguimiento del progreso:</p><ul><li>Porcentajes de tasa de éxito</li><li>Métricas de consistencia</li><li>Marcadores de análisis de vídeo</li></ul><h3 id="alcanzable-pero-exigente" tabindex="-1">Alcanzable pero exigente <a class="header-anchor" href="#alcanzable-pero-exigente" aria-label="Permalink to &quot;Alcanzable pero exigente&quot;">​</a></h3><p>El objetivo debe exigir crecimiento, pero debe ser realista. Un tirador del 60% que aspira al 65% es alcanzable; aspirar al 90% es una fantasía.</p><h3 id="importante" tabindex="-1">Importante <a class="header-anchor" href="#importante" aria-label="Permalink to &quot;Importante&quot;">​</a></h3><p>Los objetivos deben conectarse con tus aspiraciones más amplias y abordar las debilidades reales, no sólo lo que es fácil de mejorar.</p><h3 id="limitado-en-el-tiempo" tabindex="-1">Limitado en el tiempo <a class="header-anchor" href="#limitado-en-el-tiempo" aria-label="Permalink to &quot;Limitado en el tiempo&quot;">​</a></h3><p>Establezca plazos claros:</p><ul><li>&quot;Al final de la temporada&quot;</li><li>&quot;Dentro de 3 meses&quot;</li><li>&quot;Por el campeonato nacional&quot;</li></ul><h3 id="personalmente-significativo" tabindex="-1">+ Personalmente significativo <a class="header-anchor" href="#personalmente-significativo" aria-label="Permalink to &quot;+ Personalmente significativo&quot;">​</a></h3><p>El objetivo debe ser importante para TI, no solo para tu entrenador o tus compañeros. La motivación interna sustenta el esfuerzo cuando el progreso es lento.</p><h2 id="enfoque-en-el-proceso-vs-en-los-resultados" tabindex="-1">Enfoque en el proceso vs. en los resultados <a class="header-anchor" href="#enfoque-en-el-proceso-vs-en-los-resultados" aria-label="Permalink to &quot;Enfoque en el proceso vs. en los resultados&quot;">​</a></h2><h3 id="el-problema-con-los-objetivos-de-resultados" tabindex="-1">El problema con los objetivos de resultados <a class="header-anchor" href="#el-problema-con-los-objetivos-de-resultados" aria-label="Permalink to &quot;El problema con los objetivos de resultados&quot;">​</a></h3><p>&quot;Ganar el partido&quot; crea problemas:</p><ul><li>Ansiedad por cosas que no puedes controlar</li><li>Distracción de la ejecución</li><li>Pensamiento de todo o nada</li><li>Presión sin guía</li></ul><h3 id="el-poder-de-los-objetivos-de-proceso" tabindex="-1">El poder de los objetivos de proceso <a class="header-anchor" href="#el-poder-de-los-objetivos-de-proceso" aria-label="Permalink to &quot;El poder de los objetivos de proceso&quot;">​</a></h3><p>&quot;Ejecutar mi rutina pre-disparo a la perfección&quot; ofrece:</p><ul><li>Control total</li><li>Enfoque claro</li><li>Retroalimentación inmediata</li><li>Construye hacia resultados de forma natural</li></ul><h3 id="el-equilibrio" tabindex="-1">El equilibrio <a class="header-anchor" href="#el-equilibrio" aria-label="Permalink to &quot;El equilibrio&quot;">​</a></h3><p>Utilice objetivos de resultados para motivar y orientar. Utilice objetivos de proceso para enfocarse y ejecutar el día a día.</p><h2 id="establecimiento-de-objetivos-para-las-diferentes-fases" tabindex="-1">Establecimiento de objetivos para las diferentes fases <a class="header-anchor" href="#establecimiento-de-objetivos-para-las-diferentes-fases" aria-label="Permalink to &quot;Establecimiento de objetivos para las diferentes fases&quot;">​</a></h2><h3 id="fuera-de-temporada" tabindex="-1">Fuera de temporada <a class="header-anchor" href="#fuera-de-temporada" aria-label="Permalink to &quot;Fuera de temporada&quot;">​</a></h3><p>Centrarse en los objetivos de desarrollo:</p><ul><li>Mejoras técnicas</li><li>Acondicionamiento físico</li><li>Desarrollo de habilidades mentales</li><li>Ampliando tu paleta de lanzamientos</li></ul><h3 id="pretemporada" tabindex="-1">Pretemporada <a class="header-anchor" href="#pretemporada" aria-label="Permalink to &quot;Pretemporada&quot;">​</a></h3><p>Transición a la integración:</p><ul><li>Combinando habilidades en condiciones similares a las de un partido</li><li>Probando mejoras en la competencia amistosa</li><li>Estrategias de refinamiento</li></ul><h3 id="temporada-de-competicion" tabindex="-1">Temporada de competición <a class="header-anchor" href="#temporada-de-competicion" aria-label="Permalink to &quot;Temporada de competición&quot;">​</a></h3><p>Cambio hacia el rendimiento y el proceso:</p><ul><li>Ejecutar lo que has desarrollado</li><li>Objetivos del proceso para cada partido</li><li>Cambios técnicos mínimos</li></ul><h3 id="post-competicion" tabindex="-1">Post-competición <a class="header-anchor" href="#post-competicion" aria-label="Permalink to &quot;Post-competición&quot;">​</a></h3><p>Reflexión y planificación:</p><ul><li>Analizar lo que funcionó</li><li>Identificar áreas de crecimiento</li><li>Establecer metas para el próximo ciclo</li></ul><h2 id="errores-comunes-al-establecer-objetivos" tabindex="-1">Errores comunes al establecer objetivos <a class="header-anchor" href="#errores-comunes-al-establecer-objetivos" aria-label="Permalink to &quot;Errores comunes al establecer objetivos&quot;">​</a></h2><h3 id="demasiados-objetivos" tabindex="-1">Demasiados objetivos <a class="header-anchor" href="#demasiados-objetivos" aria-label="Permalink to &quot;Demasiados objetivos&quot;">​</a></h3><p>El enfoque es poder. 2 o 3 objetivos clave superan a 10 dispersos.</p><h3 id="solo-objetivos-de-resultados" tabindex="-1">Solo objetivos de resultados <a class="header-anchor" href="#solo-objetivos-de-resultados" aria-label="Permalink to &quot;Solo objetivos de resultados&quot;">​</a></h3><p>Sin objetivos de proceso, no tienes una hoja de ruta.</p><h3 id="sin-flexibilidad" tabindex="-1">Sin flexibilidad <a class="header-anchor" href="#sin-flexibilidad" aria-label="Permalink to &quot;Sin flexibilidad&quot;">​</a></h3><p>Los objetivos deben adaptarse a la nueva información. Aferrarse rígidamente a objetivos obsoletos desperdicia esfuerzo.</p><h3 id="objetivos-basados-en-la-comparacion" tabindex="-1">Objetivos basados en la comparación <a class="header-anchor" href="#objetivos-basados-en-la-comparacion" aria-label="Permalink to &quot;Objetivos basados en la comparación&quot;">​</a></h3><p>&quot;Ser mejor que [jugador]&quot; pone tu éxito en manos de otra persona.</p><h3 id="descuidar-los-objetivos-mentales" tabindex="-1">Descuidar los objetivos mentales <a class="header-anchor" href="#descuidar-los-objetivos-mentales" aria-label="Permalink to &quot;Descuidar los objetivos mentales&quot;">​</a></h3><p>Los objetivos técnicos y físicos dominan, pero las habilidades mentales a menudo determinan quién gana.</p><h2 id="estrategias-de-implementacion" tabindex="-1">Estrategias de implementación <a class="header-anchor" href="#estrategias-de-implementacion" aria-label="Permalink to &quot;Estrategias de implementación&quot;">​</a></h2><h3 id="escribelos" tabindex="-1">Escríbelos <a class="header-anchor" href="#escribelos" aria-label="Permalink to &quot;Escríbelos&quot;">​</a></h3><p>Los objetivos escritos tienen muchas más probabilidades de lograrse.</p><h3 id="revisar-periodicamente" tabindex="-1">Revisar periódicamente <a class="header-anchor" href="#revisar-periodicamente" aria-label="Permalink to &quot;Revisar periódicamente&quot;">​</a></h3><p>La revisión semanal mantiene los objetivos presentes y permite realizar ajustes.</p><h3 id="compartir-selectivamente" tabindex="-1">Compartir selectivamente <a class="header-anchor" href="#compartir-selectivamente" aria-label="Permalink to &quot;Compartir selectivamente&quot;">​</a></h3><p>Comparta con aquellos que lo apoyarán, no con aquellos que lo debilitarán.</p><h3 id="visualizar-el-logro" tabindex="-1">Visualizar el logro <a class="header-anchor" href="#visualizar-el-logro" aria-label="Permalink to &quot;Visualizar el logro&quot;">​</a></h3><p>Imagina periódicamente que logras tus objetivos: la sensación, el momento.</p><h3 id="seguimiento-del-progreso" tabindex="-1">Seguimiento del progreso <a class="header-anchor" href="#seguimiento-del-progreso" aria-label="Permalink to &quot;Seguimiento del progreso&quot;">​</a></h3><p>Lo que se mide se gestiona. Mantenga registros.</p><h2 id="cuando-los-objetivos-no-se-cumplen" tabindex="-1">Cuando los objetivos no se cumplen <a class="header-anchor" href="#cuando-los-objetivos-no-se-cumplen" aria-label="Permalink to &quot;Cuando los objetivos no se cumplen&quot;">​</a></h2><p>Los objetivos no alcanzados no son fracasos: son datos:</p><ol><li><strong>Analizar</strong>: ¿Por qué no se logró?</li><li><strong>Aprende</strong>: ¿Qué te enseña esto?</li><li><strong>Ajustar</strong>: Modificar el objetivo o el enfoque</li><li><strong>Continuar</strong>: La persistencia vence a la perfección</li></ol><h2 id="el-juego-mental-de-los-goles" tabindex="-1">El juego mental de los goles <a class="header-anchor" href="#el-juego-mental-de-los-goles" aria-label="Permalink to &quot;El juego mental de los goles&quot;">​</a></h2><p>Los objetivos afectan la psicología:</p><ul><li><strong>Demasiado fácil</strong>: Aburrimiento, complacencia.</li><li><strong>Demasiado difícil</strong>: Ansiedad, desánimo.</li><li><strong>Perfecto</strong>: Compromiso, fluidez, crecimiento</li></ul><p>Encuentra el punto ideal donde los objetivos sean un desafío sin abrumar.</p><hr><p>| <em>Relacionado: <a href="/es/educacion/metas/">Introducción al establecimiento de metas</a> | <a href="/es/educacion/objetivos/objetivos-inteligentes">Objetivos SMART</a> | <a href="/es/educacion/objetivos/planificacion">Planificando tu desarrollo</a></em> |</p>',88)])])}]]);export{s as __pageData,l as default};
